package com.quizrank.backend.controller;
import com.quizrank.backend.entity.*;import com.quizrank.backend.repository.*;import com.quizrank.backend.service.QuizService;import com.quizrank.backend.dto.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/quizzes") public class QuizController {private final QuizRepository r;private final QuizService s;private final QuestionRepository qr;public QuizController(QuizRepository r,QuizService s,QuestionRepository qr){this.r=r;this.s=s;this.qr=qr;}@GetMapping public List<Quiz> all(){return r.findAll();}@GetMapping("/{id}") public Quiz one(@PathVariable Integer id){return r.findById(id).orElseThrow(()->new NoSuchElementException("Quiz not found"));}@GetMapping("/subject/{id}") public List<Quiz> subject(@PathVariable Integer id){return r.findBySubjectId(id);}@GetMapping("/teacher/{id}") public List<Quiz> teacher(@PathVariable Integer id){return r.findByCreatedBy(id);}@PostMapping public Quiz create(@Valid @RequestBody CreateQuizRequest req){return s.create(req);}@GetMapping("/{id}/questions") public List<StudentQuestionResponse> questions(@PathVariable Integer id){return s.studentQuestions(id);}@GetMapping("/{id}/questions/teacher") public List<Question> teacherQuestions(@PathVariable Integer id){return qr.findByQuizIdOrderById(id);}}
